const SIZE_ORDER=Object.freeze(['tiny','small','medium','large']);
const GREEN_SET=new Set([24,25,26,27]);
const GREY_TRUNK=new Set([4,5,6,7,1]);
const BROWN_TRUNK=new Set([20,21,22,23]);
const AUTUMN=Object.freeze([20,10,11,9]);
const GREENS=Object.freeze([24,25,26,27]);
const TROPICAL_TRUNK_SET=new Set([8,20,21,22,23]);
const TRUNK_LIKE_SET=new Set([1,4,5,6,7,8,20,21,22,23]);
const FOLIAGE_SHADOW=4;

function clamp(v,min,max){return Math.max(min,Math.min(max,v));}
function mix32(value){let x=Number(value)>>>0;x^=x>>>16;x=Math.imul(x,0x7feb352d);x^=x>>>15;x=Math.imul(x,0x846ca68b);x^=x>>>16;return x>>>0;}
function hashAt(seed,x,y,salt=0){return mix32((seed>>>0)^Math.imul((Math.round(x)+0x10001)>>>0,0x9e3779b1)^Math.imul((Math.round(y)+0x20003)>>>0,0x85ebca6b)^Math.imul((salt+1)>>>0,0xc2b2ae35));}
function choose(values,seed){return values[(seed>>>0)%values.length];}
function inBounds(w,h,x,y){return x>=0&&y>=0&&x<w&&y<h;}
function point(p){return p&&Number.isFinite(Number(p.x))&&Number.isFinite(Number(p.y))?{x:Math.round(Number(p.x)),y:Math.round(Number(p.y))}:null;}
function countMask(mask){let n=0;for(const v of mask||[])n+=v?1:0;return n;}
function setMask(mask,w,h,x,y){x=Math.round(x);y=Math.round(y);if(inBounds(w,h,x,y))mask[y*w+x]=1;}
function uniquePoints(points){const out=[],seen=new Set();for(const p of points||[]){const x=Math.round(Number(p.x)),y=Math.round(Number(p.y));if(!Number.isFinite(x)||!Number.isFinite(y))continue;const k=`${x},${y}`;if(seen.has(k))continue;seen.add(k);out.push({x,y});}return out;}

function sourceHasTropicalTrunk(s){
  let count=0;for(const c of s.cells||[])if(TROPICAL_TRUNK_SET.has(c[2]))count++;
  return count>=Math.max(4,Math.round((Number(s.h)||0)*.35));
}
function sourceSizeClass(type,s){
  if(type==='bush'){if(s.h<=5)return 'tiny';if(s.h<=9)return 'small';if(s.h<=11)return 'medium';return 'large';}
  if(type==='tropical'){if(s.h<=18)return 'small';if(s.h<=23)return 'medium';return 'large';}
  if(s.h<=14)return 'small';if(s.h<=21)return 'medium';return 'large';
}
function cloneSprite(s){return {id:s.id,w:s.w,h:s.h,density:s.density,cells:s.cells.map(c=>[c[0],c[1],c[2]])};}
function scaleSprite(s,targetH,idSuffix='scaled'){
  targetH=Math.max(3,Math.round(targetH));if(targetH===s.h)return cloneSprite(s);
  const scale=targetH/s.h,targetW=Math.max(2,Math.round(s.w*scale)),seen=new Map();
  for(const [x,y,v] of s.cells){
    const x0=Math.floor(x*targetW/s.w),x1=Math.max(x0,Math.ceil((x+1)*targetW/s.w)-1);
    const y0=Math.floor(y*targetH/s.h),y1=Math.max(y0,Math.ceil((y+1)*targetH/s.h)-1);
    for(let yy=y0;yy<=y1;yy++)for(let xx=x0;xx<=x1;xx++)seen.set(`${xx},${yy}`,v);
  }
  const cells=[];for(const [k,v] of seen){const [x,y]=k.split(',').map(Number);cells.push([x,y,v]);}
  return {id:`${s.id}_${idSuffix}`,w:targetW,h:targetH,density:cells.length/(targetW*targetH),cells};
}
function exactPool(type,size){
  let base=type==='tropical'?SOURCES.tropical:type==='bush'?SOURCES.bush:SOURCES.standard;
  if(type==='tropical')base=base.filter(sourceHasTropicalTrunk);
  return base.filter(s=>sourceSizeClass(type==='autumn'||type==='evergreen'||type==='dead'?'standard':type,s)===size);
}
function nearestPool(type,size){
  let p=exactPool(type,size);if(p.length)return p;
  const idx=SIZE_ORDER.indexOf(size);
  for(let d=1;d<SIZE_ORDER.length;d++){
    for(const q of [idx-d,idx+d])if(q>=0&&q<SIZE_ORDER.length){p=exactPool(type,SIZE_ORDER[q]);if(p.length)return p;}
  }
  return type==='tropical'?SOURCES.tropical.filter(sourceHasTropicalTrunk):type==='bush'?SOURCES.bush:SOURCES.standard;
}
function requestedSize(seed){
  const base=SIZE_ORDER.indexOf(settings.baseSize),variation=clamp(Number(settings.sizeVariation)||0,0,100);
  if(base<0||variation<20)return settings.baseSize;
  const options=[base];if(base>0)options.push(base-1);if(base<SIZE_ORDER.length-1)options.push(base+1);
  const chance=variation/100;
  return ((hashAt(seed,0,0,13)/0xffffffff)<chance)?SIZE_ORDER[choose(options,hashAt(seed,1,0,17))]:settings.baseSize;
}
function nativeTargetHeight(type,size){
  const table=type==='bush'?{tiny:5,small:8,medium:10,large:12}:
    type==='tropical'?{tiny:12,small:18,medium:21,large:29}:
    type==='evergreen'?{tiny:11,small:15,medium:20,large:26}:
    {tiny:9,small:13,medium:19,large:24};
  return table[size]||table.medium;
}

function trunkMode(type,seed){
  if(type==='tropical')return 'brown';if(type==='bush')return 'none';
  if(settings.trunk==='mixed')return (hashAt(seed,2,0,19)&1)?'brown':'grey';
  return settings.trunk;
}
function remapTrunk(value,mode,seed,x,y){
  if(mode==='none')return value;
  if(GREEN_SET.has(value))return value;
  const grey=GREY_TRUNK.has(value),brown=BROWN_TRUNK.has(value);
  if(!grey&&!brown)return value;
  if(mode==='brown')return (hashAt(seed,x,y,23)&1)?20:21;
  return (hashAt(seed,x,y,23)&1)?4:5;
}
function trunkKeysForSprite(s){
  /*
   * Trunk colour is independent from the dark-grey foliage under-shadow.
   * Follow only a narrow 1–2 px trunk spine upward from the base instead of
   * flood-filling every connected grey/brown pixel in the canopy.
   */
  const rows=new Map();
  for(const c of s.cells||[]){const [x,y,v]=c;if(!TRUNK_LIKE_SET.has(v))continue;if(!rows.has(y))rows.set(y,[]);rows.get(y).push(c);}
  const centre=(s.w-1)/2,out=new Set();
  let previousX=null,gaps=0;
  const topLimit=Math.max(0,Math.floor(s.h*.44));
  for(let y=s.h-1;y>=topLimit;y--){
    let candidates=(rows.get(y)||[]).slice();
    if(!candidates.length){if(++gaps>2&&previousX!=null)break;continue;}
    gaps=0;
    candidates.sort((a,b)=>{
      const ax=previousX==null?Math.abs(a[0]-centre):Math.abs(a[0]-previousX)*2+Math.abs(a[0]-centre)*.35;
      const bx=previousX==null?Math.abs(b[0]-centre):Math.abs(b[0]-previousX)*2+Math.abs(b[0]-centre)*.35;
      return ax-bx||a[0]-b[0];
    });
    const first=candidates[0];
    if(previousX!=null&&Math.abs(first[0]-previousX)>2)continue;
    const picked=[first];
    const second=candidates.find(c=>c!==first&&Math.abs(c[0]-first[0])===1&&(previousX==null||Math.abs(c[0]-previousX)<=1.5));
    if(second)picked.push(second);
    for(const c of picked)out.add(`${c[0]},${c[1]}`);
    previousX=picked.reduce((sum,c)=>sum+c[0],0)/picked.length;
  }
  return out;
}
function remapSpriteTrunk(s,mode,seed){
  if(mode==='none')return cloneSprite(s);
  const trunk=trunkKeysForSprite(s);
  return {...s,cells:s.cells.map(([x,y,v])=>trunk.has(`${x},${y}`)?[x,y,remapTrunk(v,mode,seed,x,y)]:[x,y,v])};
}
function foliageSetFor(type){return type==='autumn'?new Set([9,10,11,20]):GREEN_SET;}
